// Add this to app.js
const express = require('express');
const xss = require('xss'); // npm install xss
const app = express();

// Security middleware for input sanitization
app.use(express.json());
app.use((req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = xss(req.query[key]);
      }
    });
  }

  // Sanitize URL parameters
  if (req.params) {
    Object.keys(req.params).forEach(key => {
      if (typeof req.params[key] === 'string') {
        req.params[key] = xss(req.params[key]);
      }
    });
  }
  next();
});

// For any future routes with user input, use validation:
const { body, validationResult } = require('express-validator');

// Example of a secure user creation endpoint
app.post('/users', [
  body('name').trim().isLength({ min: 1, max: 100 }).escape(),
  body('email').isEmail().normalizeEmail(),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Process valid data
});
```

### 2. Missing Security Headers
**Issue**: The application doesn't set important security headers, making it vulnerable to XSS, clickjacking, and other attacks.

**Recommendation**: Add security headers using helmet.js.

```javascript
// Add at the top of the file with other imports
const helmet = require('helmet'); // npm install helmet

// Add immediately after creating the app
app.use(helmet());
// Or with configuration:
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      objectSrc: ["'none'"],
    },
  },
