// config/secrets.js
require('dotenv').config(); // Load .env in development

class SecretManager {
  constructor() {
    // In production, prefer a secrets manager over environment variables
    this.isProduction = process.env.NODE_ENV === 'production';
    this.secretsCache = new Map();
  }

  get(key, required = true) {
    const value = process.env[key];

    if (required && (!value || value.includes('CANARY'))) {
      if (this.isProduction) {
        throw new Error(`Missing required secret: ${key}`);
      } else {
        console.warn(`Using placeholder secret for ${key} - DO NOT USE IN PRODUCTION`);
      }
    }

    return value;
  }

  async getFromAWS(name) {
    if (!this.isProduction) {
      return this.get(name);
    }

    // Implement AWS Secrets Manager integration
    const AWS = require('aws-sdk');
    const client = new AWS.SecretsManager();

    if (this.secretsCache.has(name)) {
      return this.secretsCache.get(name);
    }

    try {
      const response = await client.getSecretValue({ SecretId: name }).promise();
      const secret = JSON.parse(response.SecretString);
      this.secretsCache.set(name, secret);
      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${name}:`, error);
      throw error;
    }
  }
}

module.exports = new SecretManager();
