```javascript
// config/secrets.js - enhanced version with security controls

class SecretManager {
  constructor() {
    this.isProduction = process.env.NODE_ENV === 'production';
    this.secretsCache = new Map();
    this.loadedSources = new Set();
  }

  async init() {
    // Load from appropriate source based on environment
    if (this.isProduction) {
      await this.loadFromSecretsManager();
    } else {
      this.loadFromEnv();
    }
  }

  loadFromEnv() {
    // Only load from .env in non-production
    if (this.isProduction) return;

    const dotenv = require('dotenv');
    const fs = require('fs');
    const path = '.env';

    if (fs.existsSync(path)) {
      const result = dotenv.config({ path });
      if (result.error) {
        console.warn('Failed to load .env file:', result.error);
      } else {
        this.loadedSources.add('env_file');
        console.log('Loaded secrets from .env file');
      }
    }
  }

  async loadFromSecretsManager() {
    // Implement production secrets loading
    try {
      // AWS Secrets Manager example
      const AWS = require('aws-sdk');
      const client = new AWS.SecretsManager();

      const secretName = process.env.SECRETS_MANAGER_NAME || 'app-secrets';
      const data = await client.getSecretValue({ SecretId: secretName }).promise();

      const secrets = JSON.parse(data.SecretString);
      Object.keys(secrets).forEach(key => {
        process.env[key] = secrets[key];
      });

      this.loadedSources.add('secrets_manager');
      console.log('Loaded secrets from AWS Secrets Manager');

    } catch (error) {
      console.error('Failed to load secrets from manager:', error);
      throw error;
    }
  }

  get(key, required = true) {
    const value = process.env[key];

    // Validate that secret doesn't contain placeholder patterns
    const isPlaceholder = value && (
      value.includes('CANARY') || 
      value.includes('YOUR_') || 
      value.includes('EXAMPLE') ||
      value.length === 0
    );

    if (required && (!value || isPlaceholder)) {
      const errorMessage = `Missing or invalid secret: ${key}`;

      if (this.isProduction) {
        throw new Error(errorMessage);
      } else {
        console.warn(errorMessage);
        // Return empty string or throw in strict mode
        return process.env.STRICT_MODE ? null : value || '';
      }
    }

    return value;
  }
}

module.exports = new SecretManager();
```

