function verifySecrets() {
  const envFile = path.join(__dirname, '../.env');

  if (!fs.existsSync(envFile)) {
    console.log('No .env file found - using environment variables');
    return;
  }

  const content = fs.readFileSync(envFile, 'utf8');
  const hasRealSecrets = [
    'CANARY',
    'YOUR_',
    'EXAMPLE',
    'localhost'
  ].some(placeholder => content.includes(placeholder));

  if (hasRealSecrets) {
    console.warn('Warning: .env file contains placeholder values, please update with real secrets');
  }

  // Check for accidental commit of real AWS keys
  if (content.includes('AKIA') && !content.includes('YOUR_AWS_ACCESS_KEY')) {
    console.error('Potential AWS key detected - ensure this is not a real key');
    process.exit(1);
  }
}

if (require.main === module) {
  verifySecrets();
}

module.exports = verifySecrets;
